const char* NpthResolveSignalName(int signo) noexcept {
    switch (signo) {
        case 4:  return "SIGILL";
        case 5:  return "SIGTRAP";
        case 6:  return "SIGABRT";
        case 7:  return "SIGBUS";
        case 8:  return "SIGFPE";
        case 11: return "SIGSEGV";
        case 16: return "SIGSTKFLT";
        case 31: return "SIGSYS";
        default: return "UNKNOWN_SIG";
    }
}

int NpthFormatSignalMonitorLog(const NpthSignalEventAbi* ev, char* out_buf, std::size_t cap) noexcept {
    if (ev == nullptr || out_buf == nullptr || cap == 0U) return -1;
    return std::snprintf(
        out_buf, cap,
        "monitor_handler callback thread receied signal %d, code %d, pc=%p, addr=%p, npth_signal_init=%p",
        ev->signo, ev->si_code,
        reinterpret_cast<const void*>(ev->fault_pc),
        reinterpret_cast<const void*>(ev->fault_addr),
        reinterpret_cast<const void*>(ev->signal_init_fn));
}

